def loudAndRich(richer: list[list[int]], quiet: list[int]) -> list[int]:
    n = len(quiet)
    from collections import defaultdict
    graph = defaultdict(list)
    for u, v in richer:
        graph[v].append(u)
    ans = [-1] * n
    def dfs(u):
        if ans[u] != -1: return ans[u]
        ans[u] = u
        for v in graph[u]:
            cand = dfs(v)
            if quiet[cand] < quiet[ans[u]]:
                ans[u] = cand
        return ans[u]
    for i in range(n):
        dfs(i)
    return ans

